-- V10__add_historical_orders.sql
-- Add more historical order data so the Holt-Winters forecast
-- algorithm has sufficient data points to produce non-zero predictions.

-- ── Historical Orders ─────────────────────────────
-- Add orders across the last 30 days for each product
ON CONFLICT (id) DO NOTHING;

-- Update order_search_view for new orders
ON CONFLICT (order_id) DO UPDATE
    SET product_name = EXCLUDED.product_name, status = EXCLUDED.status, quantity = EXCLUDED.quantity, created_at = EXCLUDED.created_at;
